stageRows.noteAfterStage:
{
  "rules": [
    {
      "id": "P1-L1",
      "quote": "Implement `parse_amount(s)`."
    },
    {
      "id": "P1-L2",
      "quote": "Store and calculate every amount as an integer number of cents: `\"12.30\"` becomes `1230`, `\"3\"` becomes `300`, and `\"-2.00\"` becomes `-200`."
    },
    {
      "id": "P1-L3",
      "quote": "Inputs use ordinary decimal notation with at most two fractional digits."
    },
    {
      "id": "P1-L4",
      "quote": "Return `None` for malformed or non-string input without raising or printing."
    },
    {
      "id": "P1-L5",
      "quote": "Implement `parse_record(line)`."
    },
    {
      "id": "P1-L6",
      "quote": "Every line has exactly five `|`-separated fields: ```text TYPE|RECORD_ID|ORDER_ID|AMOUNT|TIMESTAMP ``` `TYPE` is `ORDER` or `PAYMENT`, matched case-insensitively and stored uppercase."
    },
    {
      "id": "P1-L7",
      "quote": "Trim both identifiers and reject the row if either becomes empty."
    },
    {
      "id": "P1-L8",
      "quote": "For an `ORDER`, `RECORD_ID` and `ORDER_ID` must be equal."
    },
    {
      "id": "P1-L9",
      "quote": "Record IDs are unique in the input."
    },
    {
      "id": "P1-L10",
      "quote": "Parse `AMOUNT` with `parse_amount`;"
    },
    {
      "id": "P1-L11",
      "quote": "a negative order is invalid, while a negative payment is a refund."
    },
    {
      "id": "P1-L12",
      "quote": "`TIMESTAMP` uses `YYYY-MM-DD HH:MM` and is stored as a naive `datetime`."
    },
    {
      "id": "P1-L13",
      "quote": "Return an ordinary dictionary with exactly `type`, `record_id`, `order_id`, `amount`, and `timestamp`, or `None` for any invalid row."
    },
    {
      "id": "P1-L14",
      "quote": "Invalid rows are handled silently."
    },
    {
      "id": "P1-L15",
      "quote": "Implement `load_records(text)`."
    },
    {
      "id": "P1-L16",
      "quote": "Parse each line with `parse_record`, silently skip invalid rows, and preserve source order."
    },
    {
      "id": "P1-L17",
      "quote": "Empty or non-string input returns an empty list."
    }
  ],
  "checks": [
    {
      "assertion": "assert parse_amount('12.30') == 1230",
      "result": "OBSERVED_PASS",
      "ttl": 2
    },
    {
      "assertion": "assert parse_amount('3') == 300",
      "result": "OBSERVED_PASS",
      "ttl": 2
    },
    {
      "assertion": "assert parse_amount('-2.00') == -200",
      "result": "OBSERVED_FAIL",
      "ttl": 1
    }
  ],
  "status": {},
  "todo": []
}

